flags.typeql:
match
$e isa offshore_entity, has name "TIANSHENG INDUSTRY AND TRADING CO., LTD.";
$other isa offshore_entity;
same_name_as ($e, $other);
not { $e is $other; };
fetch {
  "name": $other.name
};

match
$e isa offshore_entity, has name $en;
$o isa officer, has name $on;
$rel isa officer_of (officer: $o, offshore_entity: $e), has start_date $sd;
$sd >= 1999-01-01;
fetch {
  "EntityName": $en,
  "OfficerName": $on,
  "ConnectionStartDate": $sd
};

match
$e isa offshore_entity, has status "Active";
fetch {
  "countries": $e.countries,
  "jurisdiction": $e.jurisdiction
};

match
$e isa offshore_entity, has status "Active", has name $n;
officer_of (officer: $o, offshore_entity: $e);
reduce $officer_count = count($o) groupby $e, $n;
match $officer_count > 1;
fetch { "entityName": $n, "officerCount": $officer_count };

match
$e isa offshore_entity, has jurisdiction $j;
$a isa postal_address, has countries "Hong Kong";
registered_address (registrant: $e, registered_addr: $a);
not { $j == "HKG"; };
fetch {
  "entity_name": $e.name,
  "jurisdiction": $j,
  "address": $a.address
};

match
$a isa postal_address, has address $addr;
{
  $r1 isa offshore_entity;
  $r2 isa offshore_entity;
  registered_address (registered_addr: $a, registrant: $r1);
  registered_address (registered_addr: $a, registrant: $r2);
  not { $r1 is $r2; };
} or {
  $r1 isa officer;
  $r2 isa officer;
  registered_address (registered_addr: $a, registrant: $r1);
  registered_address (registered_addr: $a, registrant: $r2);
  not { $r1 is $r2; };
};
limit 3;
fetch { "sharedAddress": $addr };

match
$a isa postal_address, has address "ORION HOUSE SERVICES (HK) LIMITED ROOM 1401; 14/F.";
registered_address (registrant: $e, registered_addr: $a);
$e has name $name;
try { $e has address $addr; };
fetch {
  "entity_name": $name,
  "entity_address": $addr
};

match
$a isa postal_address, has address $addr;
registered_address (registrant: $e, registered_addr: $a);
reduce $count = count($e) groupby $a, $addr;
match $count >= 2;
fetch { "common_address": $addr, "entity_count": $count };

match
$e isa offshore_entity;
$a isa postal_address, has countries "Hong Kong";
registered_address (registrant: $e, registered_addr: $a);
limit 5;
fetch {
  "entity_name": $e.name,
  "entity_address": $a.address
};

match
$o isa officer;
$e isa offshore_entity;
$i isa intermediary;
officer_of (officer: $o, offshore_entity: $e);
$rel isa intermediary_of (intermediary: $i, offshore_entity: $e);
$rel has start_date $sd;
$sd < 2015-01-01;
select $o;
distinct;
fetch { "OfficerName": $o.name };

match
$o isa officer, has source_id "Panama Papers";
$rel isa officer_of (officer: $o, offshore_entity: $e), has status "ACTIVE";
fetch {
  "name": $o.name
};

match
$e isa offshore_entity, has name "Top Games Holdings Inc.";
registered_address (registrant: $e, registered_addr: $a);
registered_address (registrant: $other, registered_addr: $a);
$other isa offshore_entity;
not { $other is $e; };
fetch {
  "entity_name": $other.name
};

match
$o isa officer, has source_id "Bahamas Leaks";
$rel isa officer_of (officer: $o), has status "ACTIVE";
fetch {
  "name": $o.name,
  "node_id": $o.node_id,
  "country_codes": $o.country_codes,
  "countries": $o.countries
};
